// Albums and photos for the photography side.
// photos.json is generated by `npm run photos` from content/<album>/ (sizes, EXIF, cover, order);
// files live in public/photos/<album>/. Album names and order are set here, alt texts in alt.json.
import manifest from './photos.json';
import altTexts from './alt.json';

export interface Exif {
  camera: string;
  /** 'built-in' for cameras without interchangeable lenses (the drone), '' when the lens is unknown. */
  lens: string;
  /** Missing for manual lenses, which report neither. */
  focal?: number;
  aperture?: number;
  shutter: string;
  iso: number;
  /** ISO date, YYYY-MM-DD */
  taken: string;
}

export interface Photo {
  id: string;
  album: string;
  /** Size of the largest file. */
  width: number;
  height: number;
  /** Widths of the AVIF files, ascending; the last one is the full size. */
  widths: number[];
  /** Widths of the JPEG fallbacks. */
  jpeg: number[];
  /** Tiny blurred preview as a data URL. */
  lqip: string;
  alt: string;
  exif?: Exif;
}

export interface Album {
  slug: string;
  name: string;
  cover?: Photo;
  photos: Photo[];
}

// Order matters: the cover grid fills column by column (see src/lib/cover-layout.js).
// Albums with a content folder but no entry here are added at the end.
const NAMES: Record<string, string> = {
  landscapes: 'Landscapes',
  astro: 'Astro',
  people: 'People',
  action: 'Action',
  wildlife: 'Wildlife',
  street: 'Street',
  city: 'City',
  aerial: 'Aerial',
};

type Generated = Record<string, { cover: string; photos: Omit<Photo, 'album' | 'alt'>[] }>;
const generated = manifest as Generated;
const alt = altTexts as Record<string, string>;

export const albums: Album[] = [...new Set([...Object.keys(NAMES), ...Object.keys(generated)])]
  .filter((slug) => generated[slug])
  .map((slug) => {
    const photos = generated[slug].photos.map((p) => ({ ...p, album: slug, alt: alt[p.id] ?? '' }));
    const name = NAMES[slug] ?? slug[0].toUpperCase() + slug.slice(1);
    return { slug, name, cover: photos.find((p) => p.id === generated[slug].cover), photos };
  });

const file = (p: Photo, w: number, ext: string) => `/photos/${p.album}/${p.id}-${w}.${ext}`;
export const avifSrcSet = (p: Photo) => p.widths.map((w) => `${file(p, w, 'avif')} ${w}w`).join(', ');
export const jpegSrcSet = (p: Photo) => p.jpeg.map((w) => `${file(p, w, 'jpg')} ${w}w`).join(', ');
export const jpegSrc = (p: Photo) => file(p, p.jpeg[0], 'jpg');

export const albumBySlug = (slug: string) => albums.find((a) => a.slug === slug);
